// webchatprefs.ts — settings of the web generation mode (2026-11-03): SVGs
// generated by the local helper driving the user's ChatGPT conversation in a
// real browser instead of an API call. Validated on read (RULE 24): a stored
// value that is not usable falls back to its default, never crashes the tab.

import { isRecord } from "./isrecord";

export interface WebChatPrefs {
  /** "Generate with web page" — which confirmation popup opens. */
  enabled: boolean;
  /** The ChatGPT conversation the helper opens (https://chatgpt.com/c/<id>). */
  url: string;
  /** Minutes to wait for a finished reply before retrying once in a new chat. */
  maxWaitMin: number;
  /** Minutes to wait for the composer (the user may still have to sign in). */
  readyTimeoutMin: number;
}

/** What one run sends to the helper, in milliseconds. */
export interface WebChatTarget {
  url: string;
  maxWaitMs: number;
  readyTimeoutMs: number;
}

export const DEFAULT_WEBCHAT_PREFS: WebChatPrefs = { enabled: false, url: "", maxWaitMin: 10, readyTimeoutMin: 3 };

const CHAT_HOSTS = new Set(["chatgpt.com", "chat.openai.com"]);
const MINUTES = { min: 1, max: 60 };

/** True for an https ChatGPT page without credentials in it. */
export function isChatUrl(raw: string): boolean {
  try {
    const url = new URL(raw.trim());
    return url.protocol === "https:" && url.username === "" && url.password === "" && CHAT_HOSTS.has(url.hostname.toLowerCase());
  } catch {
    return false;
  }
}

/** True for a ChatGPT conversation page (`/c/<id>`, also inside a GPT `/g/<gpt>/c/<id>`). */
export function isConversationUrl(raw: string): boolean {
  return isChatUrl(raw) && /^\/(?:g\/[^/]+\/)?c\/[A-Za-z0-9-]+\/?$/.test(new URL(raw.trim()).pathname);
}

export function clampMinutes(value: unknown, fallback: number): number {
  const n = Number(value);
  if (typeof value !== "number" || !Number.isFinite(n)) return fallback;
  return Math.min(MINUTES.max, Math.max(MINUTES.min, Math.round(n)));
}

export function parseWebChatPrefs(raw: unknown): WebChatPrefs {
  if (!isRecord(raw)) return DEFAULT_WEBCHAT_PREFS;
  return {
    enabled: raw.enabled === true,
    url: typeof raw.url === "string" ? raw.url.trim() : "",
    maxWaitMin: clampMinutes(raw.maxWaitMin, DEFAULT_WEBCHAT_PREFS.maxWaitMin),
    readyTimeoutMin: clampMinutes(raw.readyTimeoutMin, DEFAULT_WEBCHAT_PREFS.readyTimeoutMin),
  };
}

/** The run target of these settings, or the reason nothing can be sent. */
export function webChatTargetOf(prefs: WebChatPrefs): { ok: true; target: WebChatTarget } | { ok: false; problem: string } {
  if (!isChatUrl(prefs.url)) return { ok: false, problem: "Enter the ChatGPT chat URL (https://chatgpt.com/c/…) first" };
  return {
    ok: true,
    target: { url: prefs.url.trim(), maxWaitMs: prefs.maxWaitMin * 60_000, readyTimeoutMs: prefs.readyTimeoutMin * 60_000 },
  };
}

/** The provider name a web version records: "Web: chatgpt.com". */
export function webProviderOf(url: string): string {
  try {
    return `Web: ${new URL(url).hostname}`;
  } catch {
    return "Web";
  }
}
